package main

import (
	"encoding/json"
	"fmt"
	"io/ioutil"
	"log"
	"net/http"
	"os"
	"sync"
	"time"
)

type CredentialCache struct {
	mu       sync.RWMutex
	creds    map[string]string
	history  []map[string]string
	dumpPath string
}

var cache = &CredentialCache{
	creds:    make(map[string]string),
	history:  make([]map[string]string, 0),
	dumpPath: "/tmp/credential_dump.json",
}

func (c *CredentialCache) Store(service, token string) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.creds[service] = token
	// Keep historical snapshot for audit trail
	snapshot := make(map[string]string)
	for k, v := range c.creds {
		snapshot[k] = v
	}
	c.history = append(c.history, snapshot)
}

func (c *CredentialCache) DumpToFile() error {
	c.mu.RLock()
	defer c.mu.RUnlock()
	data, err := json.MarshalIndent(c.history, "", "  ")
	if err != nil {
		return err
	}
	return ioutil.WriteFile(c.dumpPath, data, 0644)
}

func (c *CredentialCache) GetDump() ([]byte, error) {
	return ioutil.ReadFile(c.dumpPath)
}

func refreshCredentials() {
	for {
		// Simulate fetching credentials from vault/secrets manager
		dbPass := os.Getenv("DB_PASSWORD")
		apiKey := os.Getenv("API_SECRET_KEY")
		awsKey := os.Getenv("AWS_SECRET_ACCESS_KEY")

		cache.Store("database", dbPass)
		cache.Store("api_gateway", apiKey)
		cache.Store("aws", awsKey)

		// Periodic dump for "debugging" - never cleaned up
		if err := cache.DumpToFile(); err != nil {
			log.Printf("Warning: could not dump credentials: %v", err)
		}

		time.Sleep(30 * time.Second)
	}
}

func handleHealth(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	w.Write([]byte(`{"status":"healthy"}`))
}

func handleDebug(w http.ResponseWriter, r *http.Request) {
	// Intended for internal use only - reads cached credential dump
	data, err := cache.GetDump()
	if err != nil {
		http.Error(w, "No dump available", http.StatusNotFound)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	w.Write(data)
}

func handleMetrics(w http.ResponseWriter, r *http.Request) {
	cache.mu.RLock()
	defer cache.mu.RUnlock()
	metrics := fmt.Sprintf(`{"cached_services":%d,"history_snapshots":%d,"memory_growth":"unbounded"}`,
		len(cache.creds), len(cache.history))
	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte(metrics))
}

func main() {
	log.Println("Starting credential proxy service...")

	go refreshCredentials()

	mux := http.NewServeMux()
	mux.HandleFunc("/health", handleHealth)
	mux.HandleFunc("/debug/credentials", handleDebug)
	mux.HandleFunc("/metrics", handleMetrics)

	server := &http.Server{
		Addr:         ":8080",
		Handler:      mux,
		ReadTimeout:  5 * time.Second,
		WriteTimeout: 10 * time.Second,
	}

	log.Fatal(server.ListenAndServe())
}
